void reprice(List<Row> rows, Lease lease) {
    try {
        for (int i = 0; i < rows.size(); i++) {
            if (i % 500 == 0 && Thread.currentThread().isInterrupted()) return;   // cooperate with cancel
            try {
                price(rows.get(i));
            } catch (PricingException e) {                                    // only what we expect
                log.warn("skipping {}", rows.get(i).id(), e);
            }
        }
    } finally {
        boolean interrupted = Thread.interrupted();
        try { lease.release(); }                                              // blocking cleanup
        finally { if (interrupted) Thread.currentThread().interrupt(); }
    }
}

